Lemma tab_reads : forall m rest (i : Z), rw_cells rsegs m G_FIELD_TABLE (CB 2080 FT_TAB_BYTES :: rest) -> 0 <= i < 130 ->
  ov_read_bytes rsegs m (Z_to_bv 64 (G_FIELD_TABLE + 16 * i)) 8 = Some (le8 (wz (ft_ptr (Z.to_nat i))))
  /\ ov_read_bytes rsegs m (Z_to_bv 64 (G_FIELD_TABLE + 16 * i + 8)) 8 = Some (le8 (wz (ft_len (Z.to_nat i)))).
Proof.
  intros m rest i C Hi. pose proof (rw_cells_bytes_at _ _ _ _ C) as B. cbn [cells_bytes cbytes] in B.
  apply bytes_at_app in B. destruct B as [B _]. unfold FT_TAB_BYTES in B.
  destruct (nth_error FT_BYNAME (Z.to_nat i)) as [pl|] eqn:N.
  2:{ exfalso. apply nth_error_None in N. rewrite FT_BYNAME_length in N. lia. }
  destruct (ft_words_nth FT_BYNAME (Z.to_nat i) pl N) as [N1 N2]. fold ft_words in N1, N2.
  unfold ft_ptr, ft_len. rewrite (nth_error_nth _ _ _ N). split.
  - replace (G_FIELD_TABLE + 16 * i) with (G_FIELD_TABLE + 8 * Z.of_nat (2 * Z.to_nat i)) by lia.
    exact (bytes_at_u64_read _ _ _ _ _ B N1).
  - replace (G_FIELD_TABLE + 16 * i + 8) with (G_FIELD_TABLE + 8 * Z.of_nat (2 * Z.to_nat i + 1)) by lia.
    exact (bytes_at_u64_read _ _ _ _ _ B N2).
Qed.

Lemma map_upd : forall {X Y} (f : X -> Y) (l : list X) k x, map f (upd l k x) = upd (map f l) k (f x).
Proof. intros X Y f l. induction l as [|y l IH]; intros [|k] x; cbn; try reflexivity. rewrite IH. reflexivity. Qed.

Lemma ft_map_upto_step : forall n, (1 <= n)%nat ->
  upd (map b8 (ft_map_upto (n - 1))) (Z.to_nat (ft_slot n)) (b8 (Z.of_nat n)) = map b8 (ft_map_upto n).
Proof.
  intros [|n'] H; [lia|]. cbn [ft_map_upto]. replace (S n' - 1)%nat with n' by lia. rewrite map_upd. reflexivity.
Qed.

Lemma ft_map_upto_0_bytes : map b8 (ft_map_upto 0) = repeat (Z_to_bv 8 0) 1367.
Proof. cbn [ft_map_upto]. apply map_repeat. Qed.

