Definition FTC_STACK : Z := 64.
Definition ftc_W (lo : Z) (sp : word) : list (Z * Z) := [(lo, bv_unsigned sp); (G_FIELD_TABLE, G_FIELD_TABLE + 3448)]%Z.

Definition ftc_post (ra sp gp tp s0 s1 s2 s3 s4 s5 s6 s7 s8 s9 s10 s11 : word) (F : bvmap 5 word) (fc : bv 32)
    (lo : Z) (m : mem) : machine_state -> Prop :=
  fun ms' => exists t0 t1 t2 a0 a1 a2 a3 a4 a5 a6 a7 t3 t4 t5 t6 m',
    ms' = MS (mkR ra sp gp tp t0 t1 t2 s0 s1 a0 a1 a2 a3 a4 a5 a6 a7
                  s2 s3 s4 s5 s6 s7 s8 s9 s10 s11 t3 t4 t5 t6)
             F (ret_pc ra) fc None m' (seg_rom rsegs)
    /\ munch (ftc_W lo sp) m m' /\ wmono rsegs m m' /\ mem_inv rsegs m'
    /\ stk rsegs m' lo (bv_unsigned sp)
    /\ rw_cells rsegs m' G_FIELD_TABLE FTCells /\ FTInit m'.

Definition ftc_stmt : Prop :=
  forall ra sp gp tp t0 t1 t2 s0 s1 a1 a2 a3 a4 a5 a6 a7 s2 s3 s4 s5 s6 s7 s8 s9 s10 s11 t3 t4 t5 t6
    (F : bvmap 5 word) fc (m : mem) (lo : Z) (j1 j2 : list byte),
  rw_cells rsegs m G_FIELD_TABLE [CB 2080 j1; CB 1367 j2; CB 1 (zeros 1)] -> FTInit m ->
  stk rsegs m lo (bv_unsigned sp) -> lo + FTC_STACK <= bv_unsigned sp -> 0xb4000 <= lo ->
  mem_inv rsegs m ->
  evt rsegs (ftc_post ra sp gp tp s0 s1 s2 s3 s4 s5 s6 s7 s8 s9 s10 s11 F fc lo m)
    (MS (mkR ra sp gp tp t0 t1 t2 s0 s1 (wz G_FIELD_TABLE) a1 a2 a3 a4 a5 a6 a7
              s2 s3 s4 s5 s6 s7 s8 s9 s10 s11 t3 t4 t5 t6)
        F (Z_to_bv 64 P_FT_CTOR) fc None m (seg_rom rsegs)).

